const makeSharedStorage = () => {
  const rows: Row[] = [];
  const thenable = (result: unknown) => ({
    then: (resolve: (value: unknown) => unknown) =>
      Promise.resolve(result).then(resolve),
  });
  const selectChain = () => {
    const chain = {
      eq: () => chain,
      in: () => chain,
      order: () => chain,
      then: (resolve: (value: unknown) => unknown) =>
        Promise.resolve({ data: rows, error: null }).then(resolve),
    };
    return chain;
  };
  const client = {
