describe("asset degradation across both transfers", () => {
  let storage: ReturnType<typeof makeSharedStorage>;

  beforeEach(() => {
    vi.clearAllMocks();
    storage = makeSharedStorage();
    stubRoamStorage();
  });

  afterEach(() => {
    vi.unstubAllGlobals();
  });

  const publish = () =>
    publishNodeAssets({
      client: storage.client,
      spaceId: 20,
      nodes: [node],
